<script setup lang="ts">
import { nextTick,ref,watch } from 'vue';
import { LoaderCircle,Package } from '@lucide/vue';
import { useI18n } from '../i18n';
import { gameDependencyPrompt,gameDependencyInstalling,gameDependencyError,gameDependencyStatus,cancelGamePrerequisites,installGamePrerequisites } from '../composables/useGamePrerequisites';
const {t}=useI18n();const panel=ref<HTMLElement|null>(null);let previous:HTMLElement|null=null;
watch(gameDependencyPrompt,async visible=>{if(visible){previous=document.activeElement instanceof HTMLElement?document.activeElement:null;await nextTick();panel.value?.focus();}else previous?.focus();});
function keydown(event:KeyboardEvent){if(event.key==='Escape'){event.stopPropagation();cancelGamePrerequisites();}if(event.key!=='Tab')return;const buttons=panel.value?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)');if(!buttons?.length){event.preventDefault();return;}const first=buttons[0]!,last=buttons[buttons.length-1]!;if(event.shiftKey&&(document.activeElement===first||document.activeElement===panel.value)){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
</script>
<template><Teleport to="body"><div v-if="gameDependencyPrompt" class="runtime-mask" @keydown="keydown"><section ref="panel" tabindex="-1" role="dialog" aria-modal="true" aria-labelledby="runtime-title" aria-describedby="runtime-body" class="runtime-panel"><h2 id="runtime-title"><Package :size="22" />{{t('components.gameRequiredTitle')}}</h2><p id="runtime-body">{{t('components.gameRequiredBody')}}</p><ul><li v-for="dll in gameDependencyStatus?.missingVcDlls" :key="dll">{{dll}}</li><li v-for="dependency in gameDependencyStatus?.missingPackages" :key="dependency.name">{{dependency.name}} ≥ {{dependency.minVersion}}</li></ul><p v-if="gameDependencyError" role="alert">{{t('components.systemOutcome.'+gameDependencyError) === 'components.systemOutcome.'+gameDependencyError ? gameDependencyError : t('components.systemOutcome.'+gameDependencyError)}}</p><p v-if="gameDependencyInstalling" role="status"><LoaderCircle :size="16" class="spin" />{{t('components.installing')}}</p><footer><button :disabled="gameDependencyInstalling" @click="cancelGamePrerequisites">{{t('components.cancel')}}</button><button :disabled="gameDependencyInstalling" @click="installGamePrerequisites">{{t('components.installContinue')}}</button></footer></section></div></Teleport></template>
<style scoped>.runtime-mask{position:fixed;inset:0;z-index:1190;display:grid;place-items:center;background:rgb(0 0 0 / .34);padding:20px}.runtime-panel{width:min(520px,100%);padding:24px;box-sizing:border-box;border-radius:var(--copper-radius-card);background:var(--copper-surface);box-shadow:var(--copper-shadow-card);color:var(--copper-text);outline:none}h2{display:flex;align-items:center;gap:10px;font-size:18px}p,li{line-height:1.6}footer{display:flex;justify-content:flex-end;gap:10px}button{border:0;padding:10px 14px;border-radius:var(--copper-radius-control);background:var(--copper-hover);color:inherit;cursor:pointer}button:last-child{background:var(--copper-accent);color:var(--copper-on-accent,#fff)}button:disabled{opacity:.6}button:focus-visible{outline:2px solid var(--copper-accent)}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.spin{animation:none}}</style>
